'use strict';
// Explicit manual campaign. Rendering, loading and draft saving never start invitations.
window.ManualInviteCampaign = (() => {
 const base='/api/scanner/operations/manual-invite-campaign', storageKey='manual-invite-campaign-v1';
 const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const handlePattern=/^[a-z][a-z0-9_]{3,31}$/i;
 function parseUsers(value){
  const users=[],issues=[],seen=new Map();
  String(value).split(/\r?\n/).forEach((raw,index)=>{
   const line=raw.trim(),number=index+1;if(!line)return;
   const address=value=>{const direct=/^@?([a-z][a-z0-9_]{3,31})$/i.exec(value),url=/^(?:https?:\/\/)?(?:www\.)?t\.me\/([a-z][a-z0-9_]{3,31})\/?$/i.exec(value);return (direct?.[1]||url?.[1]||'').toLowerCase()||null;};
   let handle=address(line);
   if(!handle){const named=/^([^@:\/]+?)(?:\s*[—–−]\s*|\s+-\s+)(.+)$/.exec(line);if(named)handle=address(named[2]);}
   if(!handle){issues.push('Строка '+number+': укажите один @username или ссылку t.me/username. Имя без адреса не подходит.');return;}
   if(seen.has(handle)){issues.push('Строка '+number+': @'+handle+' повторяет строку '+seen.get(handle)+'.');return;}
   seen.set(handle,number);users.push(handle);
  });
  return {users,issues};
 }
 const names=s=>parseUsers(s).users;
 const connected=a=>a?.connection==='connected'&&Number.isSafeInteger(a.telegram_id)&&a.telegram_id>0;
 const initial=()=>({account:'',telegram_id:null,target_id:null,target_username:null,users:'',consent_note:'',consent_confirmed:false,max_attempts:25,account_day_attempt_cap:25,success_goal:'',interval_seconds:60});
 function fieldErrors(d,accounts,groups){
  const errors={},a=accounts.find(a=>a.id===d.account),g=groups.find(g=>g.id===d.target_id),parsed=parseUsers(d.users);
  if(!connected(a)||a.telegram_id!==d.telegram_id)errors.account='Выберите подключённый аккаунт отправителя.';
  if(!g?.managed||!g.can_invite)errors.target_id='Выберите группу с правом приглашения.';
  if(parsed.issues.length)errors.users=parsed.issues.slice(0,8).join(' ')+(parsed.issues.length>8?' Ещё ошибок: '+(parsed.issues.length-8)+'.':'');
  else if(!parsed.users.length||parsed.users.length>1000)errors.users='Укажите от 1 до 1000 участников, по одному на строку.';
  if(d.consent_note.trim().length<8||d.consent_note.trim().length>500)errors.consent_note='Опишите, как получено согласие: от 8 до 500 символов.';
  if(!d.consent_confirmed)errors.consent_confirmed='Подтвердите согласие указанных участников.';
  for(const [key,label,max] of [['max_attempts','Предел попыток кампании',1000],['account_day_attempt_cap','Дневной предел аккаунта',1000],['interval_seconds','Интервал',86400]])
   if(!Number.isInteger(d[key])||d[key]<1||d[key]>max)errors[key]=label+': целое число от 1 до '+max+'.';
  const goal=d.success_goal===''||d.success_goal===null?null:Number(d.success_goal);
  if(goal!==null&&(!Number.isInteger(goal)||goal<1||goal>Math.min(1000,d.max_attempts,parsed.users.length)))errors.success_goal='Цель должна быть целым числом от 1 до '+Math.max(0,Math.min(1000,d.max_attempts||0,parsed.users.length))+' в пределах списка и попыток. Или оставьте поле пустым.';
  return errors;
 }
 function config(d,accounts,groups){
  const fields=fieldErrors(d,accounts,groups);
  if(Object.keys(fields).length){const error=Error('Проверьте отмеченные поля: '+Object.values(fields).join(' '));error.fields=fields;throw error;}
  const a=accounts.find(a=>a.id===d.account),g=groups.find(g=>g.id===d.target_id),goal=d.success_goal===''||d.success_goal===null?null:Number(d.success_goal);
  return {account:a.id,telegram_id:a.telegram_id,target_id:g.id,target_username:g.username||null,users:names(d.users),consent_note:d.consent_note.trim(),consent_confirmed:true,max_attempts:d.max_attempts,account_day_attempt_cap:d.account_day_attempt_cap,success_goal:goal,interval_seconds:d.interval_seconds};
 }
 function createModel(){return {draft:initial(),preview:null,previewRef:null,pendingConfig:null,viewBackup:null,job:null,revision:0,saveKey:'',startKey:'',confirmed:false,edit(key,value){this.draft[key]=value;this.preview=null;this.previewRef=null;this.pendingConfig=null;this.job=null;this.confirmed=false;this.saveKey='';this.startKey='';this.revision++;}};}
 const model=createModel();let accounts=[],groups=[],active=false,life=0,busy='',error='',info='',timer=null,previewExpires=0,pendingWrite='',submitted=false,touched=new Set(),validationErrors={},previewConnection={state:'ok',failures:0,delay:0},urlPreviewRequest=null;
 const root=()=>document.querySelector('#manual-invite-campaign');
 const account=()=>accounts.find(a=>a.id===model.draft.account);
 const group=()=>groups.find(g=>g.id===model.draft.target_id)||model.job?.target;
 const alive=v=>active&&v===life&&root();
 const button=(label,action,disabled=false,primary=false)=>`<button type="button" class="cc-button${primary?' cc-button-primary':''}" data-mic="${action}"${disabled?' disabled':''}>${h(label)}</button>`;
 const isQuick=j=>j?.resolution==='on_dispatch';
 const validDigest=j=>typeof j?.config_digest==='string'&&/^[a-f0-9]{64}$/.test(j.config_digest);
 const stateLabels={draft:'Черновик',running:'Выполняется',waiting:'Ожидает следующей попытки',paused:'На паузе',interrupted:'Прервана',stopped:'Остановлена',completed:'Завершена',pending:'Ожидает',sending:'Выполняется',already_member:'Уже в группе',restricted:'Отказ Telegram',uncertain:'Результат не подтверждён',failed:'Не добавлен',blocked:'Действие ограничено',duplicate_skipped:'Повтор пропущен',cancelled:'Отменён'};
 const reasons={max_attempts_reached:'Достигнут предел попыток кампании',campaign_attempt_cap_reached:'Достигнут предел попыток кампании',process_restart:'Процесс перезапущен: автоматического продолжения нет',worker_cancelled:'Выполнение прервано',owner_pause:'Пауза по вашей команде',account_day_attempt_cap_reached:'Достигнут дневной предел попыток аккаунта',verified_goal_reached:'Достигнута цель подтверждённых новых участников',all_selected_processed:'Весь список обработан',manual_pause:'Пауза по вашей команде'};
 function safeReason(value){
  if(typeof value!=='string')return '';
  return value.trim().slice(0,1200)
   .replace(/\b(authorization\s*:\s*bearer)\s+[^\s<>"']+/gi,'$1 [скрыто]')
   .replace(/\b(api[_-]?hash|api[_-]?key|api[_-]?id|access[_-]?hash|auth[_-]?key|(?:proxy[_-]?)?password|passwd|(?:bot[_-]?)?token|(?:client[_-]?)?secret|session(?:_string)?)\b\s*[:=]\s*(?:"[^"]*"|'[^']*'|[^\s,;<>]+)/gi,'$1=[скрыто]')
   .replace(/(https?:\/\/)[^\s\/@]+:[^\s\/@]+@/gi,'$1[скрыто]@')
   .replace(/\b[A-Za-z0-9_-]{43,}\b/g,'[скрыто]');
 }
 const diagnosisCode=value=>typeof value==='string'&&/^[A-Za-z][A-Za-z0-9_]{0,79}$/.test(value)?value:null;
 const diagnosticReasons={PeerFloodError:'Telegram ограничил действия этого аккаунта. Автоматического повтора нет.',FloodWaitError:'Telegram потребовал паузу для этого аккаунта.',UserNotMutualContactError:'Telegram потребовал взаимный контакт для этого получателя.',UserPrivacyRestrictedError:'Настройки приватности этого получателя запрещают приглашение.',privacy_restricted:'Настройки приватности этого получателя запрещают прямое добавление.',invite_membership_unconfirmed:'Членство после запроса не подтверждено. Автоматического повтора нет.'};
 function diagnosisDetails(item){
  const primary=item?.diagnosis&&typeof item.diagnosis==='object'?item.diagnosis:{},nested=primary.verification_error;
  const source=nested&&typeof nested==='object'&&(diagnosisCode(nested.code)||safeReason(nested.reason))?nested:primary;
  const code=diagnosisCode(source.code),reason=safeReason(source.reason);
  if(!code&&!reason&&!['restricted','uncertain','blocked','failed'].includes(item?.state))return null;
  return {code,reason:reason||diagnosticReasons[code]||'Подробная причина не сохранена; проверьте журнал.',nested:source===nested};
 }
 function stopDetails(job){
  if(reasons[job.stop_reason])return {code:null,reason:reasons[job.stop_reason]};
  if(['stopped','interrupted'].includes(job.state)){
   const latest=(job.items||[]).filter(item=>['invited','restricted','uncertain','blocked','failed','sending','already_member'].includes(item.state)).map((item,index)=>({item,index,time:Date.parse(item.attempted_at||item.finished_at)||0})).sort((a,b)=>b.time-a.time||b.index-a.index)[0]?.item;
   if(latest&&['restricted','uncertain','blocked','failed'].includes(latest.state)){const details=diagnosisDetails(latest);if(details?.code||safeReason(latest.diagnosis?.reason)||safeReason(latest.diagnosis?.verification_error?.reason))return details;}
  }
  return {code:diagnosisCode(job.stop_reason),reason:'Причина остановки не уточнена в сохранённом результате; проверьте журнал.'};
 }
 function detailView(details){return details?`${h(details.reason)}${details.code?` <code class="mic-cause-code">${h(details.code)}</code>`:''}`:'';}
 function stopView(job){return job.stop_reason?`<p class="cc-notice" role="status"><strong>Причина остановки:</strong> ${detailView(stopDetails(job))}</p>`:'';}
 function recipientDetailView(item){const details=diagnosisDetails(item);return details?`<span class="mic-item-reason">${detailView(details)}</span>`:'';}
 function connectionView(){const id=model.job?.config?.account||model.draft.account;if(!id)return '';const a=accounts.find(a=>a.id===id);const labels={connected:'подключено',not_connected:'не подключено',code_required:'ожидается код входа',password_required:'ожидается пароль'};return `<p class="cc-help" data-mic-connection>Соединение в последнем ответе панели: <strong>${h(labels[a?.connection]||'состояние не подтверждено')}</strong>. Подключение не подтверждает разрешение приглашать участников.</p>`;}
 function protectionView(job=null){const reason=senderError(job);if(!reason)return '';const peerFlood=/PeerFlood|PEER_FLOOD|Telegram ограничил действия аккаунта/i.test(reason);return `<div class="cc-error" role="status"><strong>Приглашения приостановлены по сохранённому отказу.</strong><p>Исходящие остановлены: ${h(reason)}</p><p>Это сохранённая причина остановки, а не новая проверка Telegram. Время прежнего отказа аккаунта этим ответом не передано.${peerFlood?' Для сохранённого PeerFloodError срок окончания не указан. Панель не знает, когда ограничение снимется.':''}</p><p>Сохранение кампании не приглашает людей и остаётся доступно. Проверка соединения сохраняет остановку. Разрешение исходящих в панели выполняется отдельно после проверки аккаунта в Telegram и не снимает ограничения Telegram.</p><a class="cc-link" href="#operations" data-simple-tab="accounts">Открыть аккаунты</a></div>`;}
 function recordedStopView(job){if(!job||!job.stop_reason&&!job.stopped_at)return '';const date=typeof job.stopped_at==='string'?Date.parse(job.stopped_at):NaN,code=stopDetails(job).code||diagnosisCode(job.stop_reason);const stamp=Number.isFinite(date)?`<time datetime="${h(job.stopped_at)}">${h(new Intl.DateTimeFormat('ru-RU',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',timeZoneName:'short'}).format(new Date(date)))}</time>`:'время остановки не передано';return `<p class="cc-help" data-mic-recorded-stop>Последняя сохранённая остановка этой кампании №${h(job.job_id)}: ${stamp}${code?` · <code class="mic-cause-code">${h(code)}</code>`:''}. Это время остановки данной кампании, а не время последней ошибки аккаунта.</p>`;}
 function senderError(job=null){const value=job&&Object.hasOwn(job,'sender_error')?job.sender_error:accounts.find(a=>a.id===(job?.config?.account||model.draft.account))?.error;return typeof value==='string'?safeReason(value):value?'Сохранена ошибка аккаунта':'';}
 function senderUnavailable(job){const a=accounts.find(a=>a.id===job?.config?.account);return !connected(a)||a.telegram_id!==job.config.telegram_id||!!senderError(job);}
 async function checkStartState(job,v){const fresh=await api('/status?job_id='+job.job_id);if(!alive(v))return null;binding(fresh,job.config);if(fresh.job_id!==job.job_id||isQuick(job)&&(!isQuick(fresh)||fresh.config_digest!==job.config_digest))throw Error('Настройки или кампания изменились. Обновите состояние.');model.job=fresh;persist();if(senderUnavailable(fresh))throw Error('Исходящие аккаунта остановлены'+(senderError(fresh)?': '+senderError(fresh):' или подключение изменилось')+'. Проверка соединения не снимает остановку и ограничения Telegram. Сначала отдельно проверьте аккаунт и разрешение исходящих в панели.');if(fresh.state!=='draft'&&!fresh.can_resume)throw Error('Кампания не готова к запуску. Обновите состояние.');return fresh;}
 function previewCache(){const ref=model.previewRef;if(!ref)return null;return {id:ref.id,config:ref.config,revision:ref.revision,jobId:ref.jobId??null,target:ref.target,checked:ref.checked||0,total:ref.total||ref.config.users.length,createdAt:ref.createdAt,expiresAt:ref.expiresAt||0};}
 function persist(){try{sessionStorage.setItem(storageKey,JSON.stringify({draft:model.draft,jobId:model.job?.job_id||null,saveKey:model.saveKey,startKey:model.startKey,pendingWrite,pendingConfig:model.pendingConfig,viewBackup:model.viewBackup,revision:model.revision,previewRef:previewCache()}));}catch{}}
 function restore(){urlPreviewRequest=null;model.job=null;model.preview=null;model.previewRef=null;previewExpires=0;previewConnection={state:'ok',failures:0,delay:0};try{const s=JSON.parse(sessionStorage.getItem(storageKey));if(s?.draft&&typeof s.draft==='object')model.draft={...initial(),...s.draft};if(typeof s?.saveKey==='string')model.saveKey=s.saveKey;if(typeof s?.startKey==='string')model.startKey=s.startKey;pendingWrite=s?.pendingWrite||'';model.pendingConfig=s?.pendingConfig&&typeof s.pendingConfig==='object'?s.pendingConfig:null;model.viewBackup=s?.viewBackup&&typeof s.viewBackup==='object'?s.viewBackup:null;if(Number.isSafeInteger(s?.revision)&&s.revision>=0)model.revision=s.revision;const ref=s?.previewRef;if(ref&&typeof ref.id==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(ref.id)&&ref.config&&ref.revision===model.revision)model.previewRef={id:ref.id,config:ref.config,revision:ref.revision,jobId:ref.jobId??null,target:ref.target,checked:ref.checked||0,total:ref.total||0,createdAt:ref.createdAt,expiresAt:ref.expiresAt||0};return Number.isSafeInteger(s?.jobId)?s.jobId:null;}catch{return null;}}
 function connectionError(message,status){const e=Error(message);e.status=status;e.transient=status===undefined||status===429||status>=500;return e;}
 async function api(path,body,absolute=false){
  let response;try{response=await fetch((absolute?'/api/scanner/operations':base)+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{'X-Scanner-Request':'1',...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(path.startsWith('/destinations')?65000:['/quick-draft','/quick-start'].includes(path)?35000:25000)});}catch{throw connectionError('Нет ответа сервера. Обновите состояние перед повтором действия.');}
  let value;try{value=await response.json();}catch{throw connectionError('Сервер не подтвердил результат. Обновите состояние.',response.status>=400?response.status:undefined);}
  if(!response.ok){let message=typeof value?.detail==='string'?value.detail:response.status===403?'Недостаточно прав для ручной кампании.':'Не удалось выполнить действие. Проверьте поля и состояние.';message=message.replace(/[A-Za-z0-9_-]{43}/g,'[скрыто]');throw connectionError(message,response.status);}
  return value;
 }
 function currentConfig(){return config(model.draft,accounts,groups);}
 function valid(){try{currentConfig();return true;}catch{return false;}}
 function hasProof(){return model.preview?.state==='ready'&&typeof model.preview.candidate_token==='string'&&previewExpires>Date.now();}
 function binding(r,c){if(r?.account!==c.account||r.telegram_id!==c.telegram_id||r.target?.id!==c.target_id||JSON.stringify(r.config)!==JSON.stringify(c)){
  // Compare fields independently: JSON key order is not part of the server contract.
  if(r?.account!==c.account||r.telegram_id!==c.telegram_id||r.target?.id!==c.target_id||Object.keys(c).some(k=>JSON.stringify(r?.config?.[k])!==JSON.stringify(c[k])))throw Error('Аккаунт, группа или настройки изменились. Проверьте список заново.');
 }}
 function summary(){const d=model.draft,a=account(),g=group();return `<dl class="cc-review"><dt>Аккаунт</dt><dd>${h(a?.username?'@'+a.username:a?.label||d.account||'Не выбран')} · ${h(d.telegram_id||'—')}</dd><dt>Группа</dt><dd>${h(g?.title||'Не выбрана')}${g?.username?' · @'+h(g.username):''}</dd><dt>Список</dt><dd class="mic-users">${h(names(d.users).map(u=>'@'+u).join(', ')||'Не заполнен')}</dd><dt>Пределы</dt><dd>${h(d.max_attempts)} попыток кампании · ${h(d.account_day_attempt_cap)} попыток аккаунта в сутки · интервал ${h(d.interval_seconds)} сек.</dd><dt>Цель новых</dt><dd>${h(d.success_goal||'До обработки списка в пределах попыток')}</dd></dl>`;}
 function previewView(){const p=model.preview;if(!p)return '';return `<section class="cc-settings-section"><h2>2. Проверка списка</h2>${summary()}${previewConnection.state==='retrying'?`<p class="cc-notice" role="status">Связь с сервером прервалась. Повторим чтение состояния через ${previewConnection.delay/1000} сек. Приглашения не запускаются.</p>`:previewConnection.state==='exhausted'?'<p class="cc-error" role="status">Не удалось восстановить связь. Автоматическое обновление остановлено. Нажмите «Обновить проверку», чтобы прочитать состояние той же проверки.</p>':''}${model.previewRef||urlPreviewRequest?button('Обновить проверку','refresh-preview',!!busy):''}${p.state==='checking'?`<p role="status">${previewConnection.state==='ok'?'Проверяем участников:':'Последнее состояние: проверено'} ${h(p.checked||0)} из ${h(p.total||names(model.draft.users).length)}. Это может занять несколько минут.</p><progress max="${h(p.total||1)}" value="${h(p.checked||0)}" aria-label="Проверка участников"></progress>`:p.state==='ready'?`${previewExpires<=Date.now()?`<p class="cc-error" role="status">Срок проверки истёк. Для сохранения или запуска начните новую проверку вручную.</p>${button('Начать новую проверку',model.job?'recheck':'preview',!!busy)}`:'<p class="cc-notice">Список проверен. Приглашения ещё не запускались.</p>'}<p>Попыток аккаунта сегодня: ${h(p.account_attempts_today)}. Остаток при выбранном дневном пределе: ${h(p.remaining_attempts_today)}.</p><ol class="mic-list">${(p.selected||[]).map(i=>`<li>@${h(i.username)} · ${i.member===true?'уже в группе':i.member===false?'ещё не в группе':'членство не подтверждено'}${i.history?' · есть в истории':''}</li>`).join('')}</ol><p class="cc-help">«Уже в группе» и повторы не считаются новыми участниками. Дневной предел задаёт панель; Telegram может остановить добавления раньше.</p>${!model.job?button('Сохранить черновик','draft',!!busy||!hasProof(),true):''}`:p.state==='failed'?`<p class="cc-error" role="alert">${h(p.error||'Проверка недоступна. Начните новую проверку вручную.')}</p>${button('Начать новую проверку',model.job?'recheck':'preview',!!busy)}`:''}</section>`;}
 function resultView(){const j=model.job;if(!j)return '';const c=j.counts||{},running=['running','waiting'].includes(j.state),quick=isQuick(j),canConfirm=j.state==='draft'||j.can_resume;
  return `<section class="cc-settings-section"><h2>${quick?'2':'3'}. ${h(stateLabels[j.state]||j.state)} · №${h(j.job_id)}</h2>${summary()}
  <dl class="cc-review"><dt>Подтверждённых новых</dt><dd>${h(c.added??0)}</dd><dt>Попытки кампании</dt><dd>${h(c.attempts??0)} из ${h(j.config.max_attempts)}</dd><dt>Попытки аккаунта сегодня</dt><dd>${h(j.account_attempts_today??'—')} из ${h(j.config.account_day_attempt_cap)}</dd><dt>Осталось дневных попыток</dt><dd>${h(Number.isInteger(j.account_attempts_today)?Math.max(0,j.config.account_day_attempt_cap-j.account_attempts_today):'—')}</dd><dt>Уже в группе</dt><dd>${h(c.already_member??0)}</dd><dt>Отказы и приватность Telegram</dt><dd>${h(c.restricted??0)}</dd><dt>Результат не подтверждён</dt><dd>${h(c.uncertain??0)}</dd><dt>Ожидают</dt><dd>${h(c.pending??0)}</dd></dl>
  ${j.pause_requested===true&&running?'<p class="cc-notice" role="status">Останавливаем после текущего запроса.</p>':''}${stopView(j)}${recordedStopView(j)}
  ${j.state==='draft'?`<p class="cc-notice">${quick?'Кампания сохранена':'Черновик сохранён'}. Приглашения ещё не запускались. Проверьте состав и отдельно подтвердите запуск.</p>`:''}
  ${quick?'<p class="cc-help">Перед каждой попыткой проверяются только текущий профиль, права аккаунта и членство в группе. Это техническая проверка; согласие участников подтверждаете вы. Число новых участников зависит от ответов Telegram.</p>':j.can_resume?'<p class="cc-help">Для продолжения сначала проверьте оставшихся участников заново.</p>':''}
  ${canConfirm?`${!quick?button('Проверить перед запуском','recheck',!!busy):''}<label class="cc-ack"><input type="checkbox" data-mic-field="confirmed"${model.confirmed?' checked':''}${busy?' disabled':''}><span>Проверил аккаунт, группу, список и пределы выше. Подтверждаю запуск только этой кампании.</span></label>${button(quick?(j.state==='draft'?'Запустить кампанию':'Продолжить кампанию'):(j.state==='draft'?'Запустить эту кампанию':'Продолжить эту кампанию'),'start',!!busy||!!pendingWrite||!model.confirmed||senderUnavailable(j)||(quick?!validDigest(j):!hasProof()),true)}`:''}
  <div class="cc-actions">${running&&j.can_pause?button(j.pause_requested===true?'Останавливаем после текущего запроса':'Приостановить эту кампанию','pause',!!busy||j.pause_requested===true):''}${button('Обновить состояние','status',!!busy)}${!running?button('Новая кампания','new',!!busy||!!pendingWrite):''}</div>${running?'<p class="cc-help">Пауза остановит эту кампанию после текущего запроса. Общая очередь и прежние задания остаются в своём состоянии.</p>':''}
  <details><summary>Результаты по участникам (${h(c.total??j.items?.length??0)})</summary><ul class="mic-list">${(j.items||[]).map(i=>`<li>@${h(i.user_name||i.username)} · ${h(i.state==='invited'?(i.diagnosis?.member_before?.member===false&&i.diagnosis?.member_after?.member===true&&i.diagnosis?.invitation_requested===true?'Подтверждён новый участник':'Результат не подтверждён'):stateLabels[i.state]||'Результат не подтверждён')}${recipientDetailView(i)}</li>`).join('')}</ul></details><p><a class="cc-link" href="#results">Общий журнал результатов</a></p></section>`;
 }
 function listCount(){const parsed=parseUsers(model.draft.users);return 'Распознано '+parsed.users.length+' профилей'+(parsed.issues.length?'. Строк с ошибками: '+parsed.issues.length:'.');}
 function shownError(key){return submitted||touched.has(key)?validationErrors[key]||'':'';}
 function attributes(key){return `data-mic-field="${key}" id="mic-${key}" aria-invalid="${shownError(key)?'true':'false'}" aria-describedby="mic-${key}-error${key==='users'?' mic-users-help':''}"`;}
 function hint(key){return `<span class="mic-field-error" id="mic-${key}-error">${h(shownError(key))}</span>`;}
 function validationSummary(){const errors=Object.entries(validationErrors).filter(([key])=>submitted||touched.has(key));return errors.length?`<strong>Чтобы сохранить кампанию, исправьте поля:</strong><ul>${errors.map(([key,value])=>`<li><button type="button" class="mic-error-link" data-mic-focus="${h(key)}">${h(value)}</button></li>`).join('')}</ul>`:'';}
 function updateValidation(){
  validationErrors=fieldErrors(model.draft,accounts,groups);
  const el=root();if(!el)return;
  for(const key of Object.keys(model.draft)){const input=el.querySelector(`[data-mic-field="${key}"]`),message=el.querySelector(`#mic-${key}-error`);if(input)input.setAttribute('aria-invalid',shownError(key)?'true':'false');if(message)message.textContent=shownError(key);}
  const summary=el.querySelector('#mic-validation-summary');if(summary)summary.innerHTML=validationSummary();const count=el.querySelector('#mic-users-count');if(count)count.textContent=listCount();
 }
 function draw(){const el=root();if(!active||!el)return;const d=model.draft,a=account();validationErrors=fieldErrors(d,accounts,groups);el.innerHTML=`<style>#manual-invite-campaign{max-width:960px;min-width:0}#manual-invite-campaign .mic-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}#manual-invite-campaign .cc-button{min-height:44px;white-space:normal;margin:4px 8px 4px 0}#manual-invite-campaign .mic-list{max-height:320px;overflow:auto;overflow-wrap:anywhere;padding-left:24px}#manual-invite-campaign .mic-list li{padding:7px 0}#manual-invite-campaign .mic-item-reason{display:block;margin-top:4px;font-size:13px;color:#526c74}#manual-invite-campaign .mic-cause-code{white-space:normal;overflow-wrap:anywhere;font-size:12px}#manual-invite-campaign .mic-users{max-height:160px;overflow:auto;overflow-wrap:anywhere}#manual-invite-campaign select,#manual-invite-campaign input,#manual-invite-campaign textarea{max-width:100%}#manual-invite-campaign progress{width:100%}#manual-invite-campaign :focus-visible{outline:3px solid var(--primary,#0b788b);outline-offset:3px}#manual-invite-campaign .cc-review dd{overflow-wrap:anywhere}@media(max-width:600px){#manual-invite-campaign .mic-grid{grid-template-columns:1fr}}#manual-invite-campaign{width:100%;margin:0 auto;color:var(--text,#18383f);font-size:15px;line-height:1.55}#manual-invite-campaign *{box-sizing:border-box}#manual-invite-campaign h1{font-size:28px;line-height:1.2;margin:16px 0 10px}#manual-invite-campaign h2{font-size:20px;margin:0 0 22px}#manual-invite-campaign h3{font-size:17px;margin:28px 0 16px}#manual-invite-campaign .cc-form,#manual-invite-campaign .cc-settings-section{display:block;background:var(--panel,#fff);border:1px solid var(--line,#dce6e8);border-radius:12px;padding:28px;margin:24px 0;min-width:0}#manual-invite-campaign fieldset{border:0;padding:0;margin:0;min-width:0}#manual-invite-campaign .cc-field{display:flex;flex-direction:column;align-items:stretch;gap:8px;margin:0 0 20px;font-weight:600;min-width:0}#manual-invite-campaign .cc-field select,#manual-invite-campaign .cc-field textarea,#manual-invite-campaign .cc-field input{display:block;width:100%;min-width:0;border:1px solid #b9cbd0;border-radius:8px;background:#fff;color:#173c43;font:inherit;font-weight:400;line-height:1.45;padding:12px 14px;min-height:48px}#manual-invite-campaign .cc-field textarea{resize:vertical;min-height:108px}#manual-invite-campaign .cc-field textarea[data-mic-field=users]{min-height:200px}#manual-invite-campaign .cc-ack{display:flex;align-items:flex-start;gap:12px;margin:16px 0;font-weight:400}#manual-invite-campaign .cc-ack input{flex:0 0 20px;width:20px;height:20px;margin:3px 0 0;accent-color:#087f8c}#manual-invite-campaign .cc-help,#manual-invite-campaign .cc-subtitle,#manual-invite-campaign .cc-bottom-note{color:#526c74;font-size:14px}#manual-invite-campaign .cc-help-box,#manual-invite-campaign .cc-notice{background:#edf7f8;border:1px solid #cbe3e6;border-radius:8px;padding:14px 16px;margin:16px 0}#manual-invite-campaign .cc-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #b9cbd0;border-radius:8px;background:#fff;color:#214d57;font:inherit;font-weight:600;padding:11px 18px;cursor:pointer}#manual-invite-campaign .cc-button-primary{background:#087e8b;border-color:#087e8b;color:#fff}#manual-invite-campaign .cc-button:disabled{background:#e5ecee;border-color:#cad6d9;color:#647a80;cursor:wait;opacity:1}#manual-invite-campaign fieldset:disabled select,#manual-invite-campaign fieldset:disabled textarea,#manual-invite-campaign fieldset:disabled input{background:#f0f4f5;color:#567079}#manual-invite-campaign .cc-error,#manual-invite-campaign .mic-error-summary{background:#fff1f0;border:1px solid #e3a09b;border-radius:8px;padding:14px 16px;color:#a22520}#manual-invite-campaign [aria-invalid=true]{border:2px solid #c13a32!important;background:#fffafa!important}#manual-invite-campaign .mic-field-error{display:block;color:#b22b25;font-size:13px;font-weight:500;line-height:1.5}#manual-invite-campaign .mic-field-error:empty{display:none}#manual-invite-campaign .mic-error-summary:empty{display:none}#manual-invite-campaign .mic-error-link{font:inherit;color:inherit;background:none;border:0;padding:0;text-align:left;text-decoration:underline;cursor:pointer}#manual-invite-campaign .mic-error-summary ul{padding-left:22px;margin:8px 0 0}#manual-invite-campaign .cc-review{display:grid;grid-template-columns:minmax(130px,1fr) 2fr;gap:10px 20px;margin:20px 0}#manual-invite-campaign .cc-review dt{color:#526c74}#manual-invite-campaign .cc-review dd{margin:0;font-weight:600}#manual-invite-campaign .cc-actions{display:flex;flex-wrap:wrap;gap:8px}#manual-invite-campaign summary{padding:12px 0;cursor:pointer}#manual-invite-campaign .cc-link{color:#087b88;text-decoration:underline;text-underline-offset:3px}@media(max-width:600px){#manual-invite-campaign .cc-form,#manual-invite-campaign .cc-settings-section{padding:18px 16px;border-radius:10px}#manual-invite-campaign h1{font-size:25px}#manual-invite-campaign .cc-review{grid-template-columns:1fr;gap:3px}#manual-invite-campaign .cc-review dd{margin-bottom:10px}#manual-invite-campaign .cc-button{width:100%;margin-right:0}}</style>
  <a class="cc-link" href="#home">На главную</a><h1>Настройки инвайтинга</h1>
  <p class="cc-subtitle">Выберите аккаунт, группу и согласованный список. Сначала сохраните кампанию, затем отдельно подтвердите запуск.</p>
  ${error?`<p class="cc-error" role="alert">${h(error)}</p>`:''}${info?`<p class="cc-notice" role="status">${h(info)}</p>`:''}
  ${pendingWrite?`<p class="cc-notice">${pendingWrite==='quick-draft-missing'?'Сохранённая кампания с этим ключом не найдена. Можно явно повторить сохранение той же кампании.':pendingWrite==='quick-draft'?'Ответ на сохранение не получен. Проверьте, сохранилась ли эта кампания.':'Ответ на предыдущее действие не получен. Обновите состояние перед повтором.'} Автоматического повторного запуска нет.</p>${pendingWrite==='quick-draft'?button('Проверить сохранение кампании','recover-draft',!!busy):pendingWrite==='quick-draft-missing'?button('Изменить настройки','edit-missing-draft',!!busy):''}`:''}
  ${!accounts.length?button('Обновить аккаунты','accounts',!!busy):''}
  <section class="cc-form"><h2>1. Аккаунт и участники</h2>
  <div id="mic-validation-summary" class="mic-error-summary" role="alert">${!model.job?validationSummary():''}</div>
  <fieldset${busy||model.job||pendingWrite?' disabled':''}>
  <label class="cc-field">Аккаунт отправителя<select ${attributes('account')}><option value="">Выберите аккаунт</option>${accounts.map(a=>`<option value="${h(a.id)}"${a.id===d.account?' selected':''}${connected(a)?'':' disabled'}>${h(a.username?'@'+a.username:a.label||a.id)} · ${h(a.telegram_id||'не подключён')}${!connected(a)?' · не подключён':!a.enabled?' · общая очередь на паузе':''}</option>`).join('')}</select>${hint('account')}</label>
  ${connectionView()}${senderError(model.job)?protectionView(model.job):a&&!a.enabled?'<p class="cc-help-box">Общая очередь аккаунта на паузе. Обычная ручная пауза без сохранённой ошибки допускает отдельно подтверждённую конечную кампанию; прежние задания не возобновляются.</p>':''}
  <label class="cc-field">Группа для приглашения<select ${attributes('target_id')}><option value="">Выберите группу</option>${groups.map(g=>`<option value="${h(g.id)}"${g.id===d.target_id?' selected':''}>${h(g.title)}${g.username?' · @'+h(g.username):''}</option>`).join('')}</select>${hint('target_id')}</label>
  ${button(busy==='groups'?'Загружаем группы…':'Обновить группы','groups',!!busy||!connected(a))}
  ${a&&!groups.length?'<p class="cc-help">Загрузите доступные управляемые группы. Нужны права приглашения участников.</p>':''}
  <label class="cc-field">Согласованный список @username<textarea ${attributes('users')} rows="7" maxlength="120000" placeholder="@username_one&#10;Имя участника — @username_two&#10;https://t.me/username_three">${h(d.users)}</textarea>${hint('users')}</label>
  <p class="cc-help" id="mic-users-count" role="status">${h(listCount())}</p><p class="cc-help" id="mic-users-help">От 1 до 1000 участников, по одному на строку: @username, username, t.me/username или Имя — @username. Имена без адреса не принимаются. Взаимный контакт не является обязательным фильтром панели.</p>
  <label class="cc-field">Как получено согласие<textarea ${attributes('consent_note')} rows="3" maxlength="500" placeholder="Укажите, когда и каким способом участники согласились вступить">${h(d.consent_note)}</textarea>${hint('consent_note')}</label>
  <label class="cc-ack"><input type="checkbox" ${attributes('consent_confirmed')}${d.consent_confirmed?' checked':''}><span>Все указанные участники согласились вступить в выбранную группу.${hint('consent_confirmed')}</span></label>
  <h3>Пределы этой кампании</h3><div class="mic-grid">${[['max_attempts','Максимум попыток кампании',1000],['account_day_attempt_cap','Дневной предел попыток аккаунта',1000],['interval_seconds','Интервал между попытками, секунд',86400],['success_goal','Цель подтверждённых новых, необязательно',1000]].map(([key,label,max])=>`<label class="cc-field">${label}<input type="number" ${attributes(key)} min="1" max="${max}" step="1" value="${h(d[key])}"${key==='success_goal'?' placeholder="Без отдельной цели"':''}>${hint(key)}</label>`).join('')}</div>
  <p class="cc-help">Это программные пределы, не квота Telegram. Попытки и подтверждённые новые участники считаются отдельно. Дневной бюджет учитывает другие задания этого аккаунта, день сбрасывается в 00:00 UTC.</p></fieldset>
  ${!model.job?button(busy==='quick-draft'?'Сохраняем кампанию…':pendingWrite==='quick-draft-missing'?'Повторить сохранение кампании':'Сохранить кампанию','quick-draft',!!busy||!!pendingWrite&&pendingWrite!=='quick-draft-missing',true):''}<p class="cc-help">Предварительный обход участников не нужен. Сохранение не приглашает людей. После отдельного запуска профили проверяются по одному непосредственно перед попыткой.</p>
  ${model.job?'<p class="cc-help">Настройки сохранённой кампании зафиксированы. Для другого списка создайте новую кампанию.</p>':''}</section>
  ${model.preview?`<details class="cc-settings-section"><summary>Прежняя проверка списка · совместимость</summary>${previewView()}</details>`:''}${resultView()}<p class="cc-bottom-note"><a class="cc-link" href="operations-guide.html#manual-invites">Как настроить приглашения</a> · <a class="cc-link" href="#invites">История и прежние инструменты</a></p>`;}
 async function loadGroups(){const a=account();if(!connected(a))throw Error('Выберите подключённый аккаунт.');const revision=model.revision,v=life,c={account:a.id,telegram_id:a.telegram_id};const r=await api('/destinations?account='+encodeURIComponent(a.id)+'&telegram_id='+a.telegram_id);if(!alive(v)||revision!==model.revision)return;if(r.account!==c.account||r.telegram_id!==c.telegram_id||!Array.isArray(r.destinations))throw Error('Группы не подтверждены для выбранного аккаунта.');groups=r.destinations.filter(g=>g.managed&&g.can_invite&&Number.isSafeInteger(g.id)&&g.id<0);if(r.username)a.username=r.username;if(draftTargetMissing())model.edit('target_id',null);persist();}
 function draftTargetMissing(){return model.draft.target_id!==null&&!groups.some(g=>g.id===model.draft.target_id);}
 function schedule(fn,delay=2000){clearTimeout(timer);timer=setTimeout(()=>{if(active&&!busy)run(fn);else if(active)schedule(fn,delay);},delay);}
 function attached(id,c,revision,v){return alive(v)&&revision===model.revision&&model.previewRef?.id===id&&model.previewRef.revision===revision&&Object.keys(c).every(k=>JSON.stringify(model.previewRef.config[k])===JSON.stringify(c[k]));}
 function finishPreview(message){urlPreviewRequest=null;model.preview={state:'failed',error:message};model.previewRef=null;model.confirmed=false;previewExpires=0;previewConnection={state:'ok',failures:0,delay:0};clearTimeout(timer);timer=null;persist();}
 async function readPreview(id,c,revision,v,cached){
  if(!attached(id,c,revision,v))return;
  if(!Number.isFinite(model.previewRef.createdAt)||Date.now()>model.previewRef.createdAt+3900000){finishPreview('Срок ожидания проверки истёк. Начните новую проверку вручную.');return;}
  let p;try{p=cached===undefined?await api('/previews/'+encodeURIComponent(id)):cached;}catch(e){
   if(!attached(id,c,revision,v))return;
   if(!e.transient){finishPreview(e.status===404?'Проверка больше недоступна. Начните новую проверку вручную.':e.message);return;}
   const delays=[2000,5000,10000,15000],failures=previewConnection.failures+1;
   previewExpires=0;model.confirmed=false;
   if(failures<=delays.length){previewConnection={state:'retrying',failures,delay:delays[failures-1]};schedule(()=>readPreview(id,c,revision,v),delays[failures-1]);}
   else previewConnection={state:'exhausted',failures,delay:0};
   persist();return;
  }
  if(!attached(id,c,revision,v))return;
  try{if(p.preview_id!==id)throw Error('Сервер вернул другую проверку. Начните новую проверку вручную.');binding(p,c);if(p.invitation_requested!==false)throw Error('Сервер не подтвердил безопасную проверку списка.');
   if(Number.isFinite(p.created_at))model.previewRef.createdAt=Math.min(model.previewRef.createdAt,p.created_at*1000);if(Date.now()>model.previewRef.createdAt+3900000){finishPreview('Срок ожидания проверки истёк. Начните новую проверку вручную.');return;}
   if(p.state==='failed'){finishPreview(p.error||'Проверка не завершена. Начните новую проверку вручную.');return;}
   if(!['checking','ready'].includes(p.state))throw Error('Неизвестное состояние проверки.');
   if(p.state==='ready'&&(!Array.isArray(p.selected)||!(/^[A-Za-z0-9_-]{43}$/.test(p.candidate_token||''))))throw Error('Проверенный список не подтверждён.');
  }catch(e){finishPreview(e.message);return;}
  error='';previewConnection={state:'ok',failures:0,delay:0};model.preview=p;
  model.previewRef={...model.previewRef,target:p.target,checked:p.checked??p.selected?.length??0,total:p.total??c.users.length};
  if(p.state==='checking')schedule(()=>readPreview(id,c,revision,v));
  else{const latest=Math.max(0,...p.selected.map(item=>Date.parse(item.checked_at)||0));const derived=latest?latest+Math.max(0,Math.min(300,p.token_ttl_seconds||0)-5)*1000:0;const known=model.previewRef.expiresAt||0;previewExpires=known&&derived?Math.min(known,derived):known||derived;model.previewRef.expiresAt=previewExpires;}persist();
 }
 async function refreshPreview(){if(urlPreviewRequest){const request=urlPreviewRequest;clearTimeout(timer);timer=null;previewConnection={state:'ok',failures:0,delay:0};return attachFromUrl(request.id,request.storedJobId,life,request.revision);}const ref=model.previewRef;if(!ref)return;clearTimeout(timer);timer=null;previewConnection={state:'ok',failures:0,delay:0};await readPreview(ref.id,ref.config,ref.revision,life);}
 async function prepare(){if(!model.job)submitted=true;const c=model.job?.config||currentConfig(),revision=model.revision,v=life;clearTimeout(timer);timer=null;model.preview=null;model.previewRef=null;model.confirmed=false;previewExpires=0;previewConnection={state:'ok',failures:0,delay:0};persist();const p=await api(model.job?'/jobs/'+model.job.job_id+'/preview':'/preview',model.job?{}:c);if(!alive(v)||revision!==model.revision)return;binding(p,c);if(typeof p.preview_id!=='string'||p.state!=='checking'||p.invitation_requested!==false)throw Error('Проверка списка не подтверждена.');consumePreviewQuery();model.preview=p;model.previewRef={id:p.preview_id,config:c,revision,jobId:model.job?.job_id??null,target:{...group(),...p.target},checked:p.checked||0,total:p.total||c.users.length,createdAt:Number.isFinite(p.created_at)?p.created_at*1000:Date.now(),expiresAt:0};persist();schedule(()=>readPreview(p.preview_id,c,revision,v));}
 async function status(){if(!model.job?.job_id)return;const id=model.job.job_id,v=life,r=await api('/status?job_id='+id);if(!alive(v)||model.job?.job_id!==id)return;binding(r,model.job.config);if(r.job_id!==id||isQuick(model.job)&&(!isQuick(r)||r.config_digest!==model.job.config_digest))throw Error('Сервер вернул другую кампанию.');model.job=r;pendingWrite='';model.startKey='';persist();if(['running','waiting'].includes(r.state))schedule(status,4000);}
 async function run(fn,type=''){if(busy)return;const v=life;busy=type||'read';error='';draw();try{await fn();}catch(e){if(alive(v)){error=e.fields?'Исправьте отмеченные поля перед сохранением кампании.':e.message||'Действие не выполнено.';if(e.fields)validationErrors=e.fields;}}finally{if(v===life){busy='';if(active){draw();if(submitted&&Object.keys(validationErrors).length&&!model.job&&['preview','quick-draft'].includes(type))root()?.querySelector('[aria-invalid="true"]')?.focus();}}}}
 function checkQuick(r,c){binding(r,c);if(!Number.isSafeInteger(r.job_id)||r.job_id<=0||!isQuick(r)||!validDigest(r))throw Error('Сервер не подтвердил сохранённую кампанию. Проверьте сохранение перед повтором.');}
 function adoptQuick(r){model.job=r;model.pendingConfig=null;model.preview=null;model.previewRef=null;model.confirmed=false;pendingWrite='';clearTimeout(timer);timer=null;persist();info=r.state==='draft'?'Кампания сохранена. Проверьте состав и подтвердите запуск.':'Кампания уже сохранена. Показано её текущее состояние.';if(['running','waiting'].includes(r.state))schedule(status,4000);}
 async function recoverQuickDraft(){if(!model.saveKey||!model.pendingConfig)return;const key=model.saveKey,c=model.pendingConfig,v=life;let r;try{r=await api('/draft-requests/'+encodeURIComponent(key));}catch(e){if(!alive(v)||key!==model.saveKey)return;if(e.status===404){pendingWrite='quick-draft-missing';info='Кампания пока не найдена. Повторное сохранение требует вашего нажатия.';persist();return;}throw e;}if(!alive(v)||key!==model.saveKey)return;checkQuick(r,c);adoptQuick(r);}
 async function saveQuick(){submitted=true;if(pendingWrite==='quick-draft')return recoverQuickDraft();if(pendingWrite&&pendingWrite!=='quick-draft-missing')throw Error('Сначала проверьте результат предыдущего действия.');const c=model.pendingConfig||currentConfig(),v=life;model.saveKey=model.saveKey||crypto.randomUUID();model.pendingConfig=c;pendingWrite='quick-draft';model.preview=null;model.previewRef=null;model.confirmed=false;urlPreviewRequest=null;clearTimeout(timer);timer=null;persist();let r;try{r=await api('/quick-draft',{config:c,request_key:model.saveKey});}catch(e){if(alive(v)&&[400,401,403,422].includes(e.status)){pendingWrite='';model.pendingConfig=null;model.saveKey='';persist();}throw e;}if(!alive(v))return;checkQuick(r,c);consumePreviewQuery();adoptQuick(r);}
 async function action(type){if(type==='edit-missing-draft'){if(pendingWrite!=='quick-draft-missing')throw Error('Сначала проверьте сохранение кампании.');pendingWrite='';model.pendingConfig=null;model.saveKey='';info='Настройки доступны для изменения. Сохранение новой версии потребует отдельного нажатия.';persist();return;}if(type==='quick-draft')return saveQuick();if(type==='recover-draft')return recoverQuickDraft();if(type==='refresh-preview')return refreshPreview();if(type==='accounts'){const r=await api('',undefined,true);if(!Array.isArray(r.accounts))throw Error('Аккаунты не загружены.');accounts=r.accounts;return;}if(type==='groups')return loadGroups();if(type==='preview'||type==='recheck'){if(urlPreviewRequest||model.previewRef&&(model.preview?.state==='checking'||previewConnection.state!=='ok'))return refreshPreview();return prepare();}if(type==='status')return status();if(type==='draft'){if(!hasProof())throw Error('Срок проверки истёк. Проверьте список заново.');const c=currentConfig(),v=life;model.saveKey=model.saveKey||crypto.randomUUID();pendingWrite='draft';persist();const r=await api('/draft',{config:c,candidate_token:model.preview.candidate_token,request_key:model.saveKey});if(!alive(v))return;binding(r,c);if(!Number.isSafeInteger(r.job_id)||r.state!=='draft')throw Error('Черновик не подтверждён. Проверьте журнал.');model.job=r;if(model.previewRef)model.previewRef.jobId=r.job_id;pendingWrite='';model.confirmed=false;persist();info='Черновик сохранён. Проверьте состав и отдельно подтвердите запуск.';return;}
  if(type==='start'){
   const quick=isQuick(model.job);if(!model.job||!model.confirmed||pendingWrite||(quick?!validDigest(model.job):!hasProof()))throw Error('Проверьте состав и подтвердите запуск этой кампании.');
   const c=model.job.config,id=model.job.job_id,v=life;const fresh=await checkStartState(model.job,v);if(!fresh)return;model.startKey=model.startKey||crypto.randomUUID();pendingWrite=quick?'quick-start':'start';persist();
   const body=quick?{job_id:id,config_digest:model.job.config_digest,request_key:model.startKey,confirmed:true}:{job_id:id,candidate_token:model.preview.candidate_token,request_key:model.startKey,confirmed:true};
   const r=await api(quick?'/quick-start':'/start',body);if(!alive(v))return;binding(r,c);if(r.job_id!==id||quick&&(!isQuick(r)||r.config_digest!==model.job.config_digest))throw Error('Запуск нужной кампании не подтверждён. Обновите состояние.');
   model.job=r;model.preview=null;model.previewRef=null;model.confirmed=false;model.startKey='';pendingWrite='';persist();schedule(status,4000);return;
  }
  if(type==='pause'){const v=life,c=model.job.config,id=model.job.job_id,r=await api('/pause',{job_id:id});if(!alive(v))return;binding(r,c);if(r.job_id!==id)throw Error('Пауза нужной кампании не подтверждена.');model.job=r;model.preview=null;model.previewRef=null;model.confirmed=false;model.startKey='';persist();schedule(status,2000);return;}
  if(type==='new'){if(pendingWrite&&pendingWrite!=='quick-draft-missing')throw Error('Сначала обновите состояние и проверьте результат предыдущего действия.');if(['running','waiting'].includes(model.job?.state))return;urlPreviewRequest=null;consumeParam('invite_job');consumePreviewQuery();clearTimeout(timer);model.job=null;model.pendingConfig=null;model.preview=null;model.previewRef=null;model.confirmed=false;model.saveKey='';model.startKey='';pendingWrite='';info='';submitted=false;touched.clear();validationErrors={};model.revision++;if(model.viewBackup){const backup=model.viewBackup;model.draft={...initial(),...backup.draft};model.saveKey=backup.saveKey||'';model.startKey=backup.startKey||'';pendingWrite=backup.pendingWrite||'';model.pendingConfig=backup.pendingConfig||null;model.previewRef=backup.previewRef||null;model.revision=Number.isSafeInteger(backup.revision)?backup.revision:model.revision;groups=backup.target?[backup.target]:[];model.viewBackup=null;info='Ваш несохранённый список восстановлен.';}persist();}
 }
 document.addEventListener('input',e=>{const t=e.target,key=t.dataset?.micField;if(!key||!t.closest('#manual-invite-campaign')||busy||model.job||['account','target_id','consent_confirmed','confirmed'].includes(key))return;clearTimeout(timer);timer=null;urlPreviewRequest=null;consumePreviewQuery();model.edit(key,['max_attempts','account_day_attempt_cap','interval_seconds'].includes(key)?Number(t.value):t.value);persist();touched.add(key);error='';root()?.querySelector('.cc-error')?.remove();updateValidation();root()?.querySelectorAll('.cc-settings-section').forEach(el=>el.remove());});
 document.addEventListener('change',e=>{const t=e.target,key=t.dataset?.micField;if(!key||!t.closest('#manual-invite-campaign')||busy)return;if(key==='confirmed'){model.confirmed=t.checked;draw();return;}if(model.job)return;clearTimeout(timer);timer=null;urlPreviewRequest=null;consumePreviewQuery();touched.add(key);error='';if(key==='account'){const a=accounts.find(a=>a.id===t.value);model.edit('account',a?.id||'');model.draft.telegram_id=a?.telegram_id||null;model.draft.target_id=null;model.draft.target_username=null;groups=[];persist();draw();if(a)run(loadGroups,'groups');}else if(key==='target_id'){const g=groups.find(g=>g.id===Number(t.value));model.edit('target_id',g?.id||null);model.draft.target_username=g?.username||null;persist();draw();}else if(key==='consent_confirmed'){model.edit(key,t.checked);persist();draw();}});
 document.addEventListener('click',e=>{const focus=e.target.closest('[data-mic-focus]');if(focus&&focus.closest('#manual-invite-campaign')&&focus.dataset.micFocus){e.preventDefault();e.stopPropagation?.();const field=root()?.querySelector('[data-mic-field="'+focus.dataset.micFocus+'"]');field?.focus();field?.scrollIntoView?.({block:'center',behavior:'smooth'});return;}const b=e.target.closest('[data-mic]');if(!b||!b.closest('#manual-invite-campaign')||b.disabled)return;e.preventDefault();run(()=>action(b.dataset.mic),b.dataset.mic);});
 function view(){return '<div id="manual-invite-campaign" aria-live="off"></div>';}
 function consumeParam(name){const params=new URLSearchParams(location.search||'');if(!params.has(name))return;params.delete(name);const query=params.toString();window.history?.replaceState?.(null,'',(location.pathname||'/')+(query?'?'+query:'')+(location.hash||''));}
 function consumePreviewQuery(){consumeParam('invite_preview');}
 function explicitJob(){const ids=new URLSearchParams(location.search||'').getAll('invite_job');if(!ids.length)return null;const id=Number(ids[0]);if(ids.length!==1||!/^\d+$/.test(ids[0])||!Number.isSafeInteger(id)||id<=0)throw Error('Некорректная ссылка на кампанию. Ваш ввод сохранён.');return id;}
 async function attachJob(id,v){const j=await api('/status?job_id='+id);if(!alive(v))return;if(j.job_id!==id||!j.config)throw Error('Сервер не подтвердил выбранную кампанию.');binding(j,j.config);if(isQuick(j)&&!validDigest(j))throw Error('Настройки выбранной кампании не подтверждены.');
  let matches=false;try{const c=config(model.draft,accounts,[{...j.target,managed:true,can_invite:true}]);matches=Object.keys(j.config).every(key=>JSON.stringify(c[key])===JSON.stringify(j.config[key]));}catch{}
  if(!matches&&meaningfulDraft(model.draft)&&!model.viewBackup)model.viewBackup={draft:{...model.draft},saveKey:model.saveKey,startKey:model.startKey,pendingWrite,pendingConfig:model.pendingConfig,previewRef:previewCache(),revision:model.revision,target:group()?{...group()}:model.draft.target_id?{id:model.draft.target_id,username:model.draft.target_username,title:model.draft.target_username||'Выбранная группа',managed:true,can_invite:true}:null};
  const raw=model.draft.users;model.job=j;model.draft={...j.config,users:matches?raw:j.config.users.map(user=>'@'+user).join('\n'),success_goal:j.config.success_goal??''};groups=[{...j.target,managed:true,can_invite:true}];model.pendingConfig=null;model.preview=null;model.previewRef=null;model.confirmed=false;model.saveKey='';model.startKey='';pendingWrite='';urlPreviewRequest=null;persist();if(['running','waiting'].includes(j.state))schedule(status,4000);
 }
 function explicitPreview(){const params=new URLSearchParams(location.search||'');const ids=params.getAll('invite_preview');if(!ids.length)return null;if(ids.length!==1||!/^[A-Za-z0-9_-]{32}$/.test(ids[0]))throw Error('Некорректная ссылка на сохранённую проверку. Ваш ввод сохранён.');return ids[0];}
 function meaningfulDraft(d){const blank=initial();return !!(d.account||d.target_id||String(d.users).trim()||d.consent_note.trim()||d.consent_confirmed||['max_attempts','account_day_attempt_cap','interval_seconds','success_goal'].some(key=>d[key]!==blank[key]));}
 async function attachFromUrl(id,storedJobId,v,revision=model.revision){
  if(!alive(v)||revision!==model.revision)return;urlPreviewRequest={id,storedJobId,revision};let p;try{p=await api('/previews/'+encodeURIComponent(id));}catch(e){if(!alive(v)||revision!==model.revision||urlPreviewRequest?.id!==id||urlPreviewRequest.revision!==revision)return;if(!e.transient){finishPreview(e.status===404?'Проверка больше недоступна. Начните новую проверку вручную.':e.message);return;}model.preview={state:'checking',checked:0,total:names(model.draft.users).length};const delays=[2000,5000,10000,15000],failures=previewConnection.failures+1;if(failures<=delays.length){previewConnection={state:'retrying',failures,delay:delays[failures-1]};schedule(()=>attachFromUrl(id,storedJobId,v,revision),delays[failures-1]);}else previewConnection={state:'exhausted',failures,delay:0};return;}if(!alive(v)||revision!==model.revision||urlPreviewRequest?.id!==id||urlPreviewRequest.revision!==revision)return;urlPreviewRequest=null;model.preview=null;previewConnection={state:'ok',failures:0,delay:0};
  if(p?.preview_id!==id)throw Error('Сервер вернул другую проверку. Ваш ввод сохранён.');const c=p?.config,target=p?.target;if(!c||!target||!Array.isArray(c.users)||!Number.isFinite(p.created_at))throw Error('Сервер не подтвердил сохранённую проверку. Ваш ввод сохранён.');
  binding(p,c);if(p.invitation_requested!==false)throw Error('Сервер не подтвердил безопасную проверку. Ваш ввод сохранён.');
  const nextGroups=[{...target,title:target.title||target.username||'Выбранная группа',managed:true,can_invite:true}];
  const incoming={...c,users:c.users.map(user=>'@'+user).join('\n'),success_goal:c.success_goal??''};
  const hasDraft=meaningfulDraft(model.draft);let current;
  try{current=config(hasDraft?model.draft:incoming,accounts,nextGroups);}catch{throw Error('Сохранённая проверка относится к другим настройкам. Ваш текущий ввод сохранён.');}
  if(storedJobId&&(storedJobId!==(p.job_id??null))||Object.keys(c).some(key=>JSON.stringify(current[key])!==JSON.stringify(c[key])))throw Error('Сохранённая проверка относится к другим настройкам. Ваш текущий ввод сохранён.');
  let job=null;if(p.job_id){job=await api('/status?job_id='+p.job_id);if(!alive(v)||revision!==model.revision)return;binding(job,c);if(job.job_id!==p.job_id)throw Error('Кампания сохранённой проверки не совпала. Ваш ввод сохранён.');}
  if(!hasDraft)model.draft=incoming;model.job=job;groups=nextGroups;model.confirmed=false;
  model.previewRef={id,config:c,revision:model.revision,jobId:p.job_id??null,target,checked:p.checked||0,total:p.total||c.users.length,createdAt:p.created_at*1000,expiresAt:model.previewRef?.id===id?model.previewRef.expiresAt||0:0};
  model.preview={state:'checking',checked:p.checked||0,total:p.total||c.users.length};persist();await readPreview(id,c,model.revision,v,p);if(alive(v)&&model.previewRef?.id===id)consumePreviewQuery();
 }
 async function mount(){active=true;const v=++life;const jobId=restore();draw();await run(async()=>{
  const r=await api('',undefined,true);if(!alive(v))return;if(!Array.isArray(r.accounts))throw Error('Аккаунты не загружены.');accounts=r.accounts;const requestedJob=explicitJob();if(requestedJob){await attachJob(requestedJob,v);return;}if(pendingWrite==='quick-draft'||pendingWrite==='quick-draft-missing'){const c=model.pendingConfig;if(c)groups=[{id:c.target_id,username:c.target_username,title:c.target_username||'Выбранная группа',managed:true,can_invite:true}];if(pendingWrite==='quick-draft')await recoverQuickDraft();return;}const requested=explicitPreview();if(requested){await attachFromUrl(requested,jobId,v);return;}const a=account();
  if(model.draft.account&&(!connected(a)||a.telegram_id!==model.draft.telegram_id)){model.edit('account','');model.draft.telegram_id=null;model.draft.target_id=null;groups=[];pendingWrite='';info='Отправитель изменился. Выберите аккаунт заново.';}
  if(jobId){const j=await api('/status?job_id='+jobId);if(!alive(v))return;if(j.job_id!==jobId||!j.config)throw Error('Сохранённая кампания не подтверждена.');model.job=j;const raw=model.draft.users,keepRaw=model.draft.account===j.config.account&&model.draft.telegram_id===j.config.telegram_id&&model.draft.target_id===j.config.target_id&&JSON.stringify(names(raw))===JSON.stringify(j.config.users);model.draft={...j.config,users:keepRaw?raw:j.config.users.map(u=>'@'+u).join('\n'),success_goal:j.config.success_goal??''};groups=[{...j.target,managed:true,can_invite:true}];pendingWrite='';if(isQuick(j)){model.previewRef=null;model.preview=null;}if(['running','waiting'].includes(j.state)){model.previewRef=null;persist();schedule(status,4000);return;}}
  const ref=model.previewRef;
  if(ref){
   const target=ref.target||{id:ref.config.target_id,username:ref.config.target_username};
   groups=[{...target,title:target.title||target.username||'Выбранная группа',managed:true,can_invite:true}];
   let matches=false;try{const c=currentConfig();matches=ref.revision===model.revision&&(ref.jobId??null)===(model.job?.job_id??null)&&Object.keys(c).every(k=>JSON.stringify(c[k])===JSON.stringify(ref.config[k]));}catch{}
   if(matches){model.preview={state:'checking',checked:ref.checked,total:ref.total};await readPreview(ref.id,ref.config,ref.revision,v);return;}
   model.previewRef=null;model.preview=null;persist();
  }
  persist();if(!jobId&&connected(account()))await loadGroups();
 },'load');}
 function unmount(){active=false;life++;busy='';clearTimeout(timer);timer=null;}
 return {view,mount,unmount,_test:{recordedStopView,protectionView,senderError,senderUnavailable,diagnosisDetails,stopDetails,safeReason,isQuick,names,parseUsers,fieldErrors,connected,initial,config,createModel}};
})();
